/* Full shell stylesheet owned by the desktop package. Every effect is author-editable. */
.os-shell {
  --os-accent:#2979ed; --os-ink:#1c2636; --os-muted:#5e6978; --os-glass:rgba(243,247,253,.86); --os-panel:#f9fbff; --os-line:rgba(255,255,255,.65); --os-divider:rgba(31,51,80,.10); --os-hover:rgba(255,255,255,.52); --os-shadow:0 22px 65px rgba(8,25,60,.22),0 1px 4px rgba(4,18,45,.12); --os-icon-size:48px; --dock-icon-size:30px; --os-enter:260ms; --os-ease:cubic-bezier(.16,1,.3,1);
  --surface-raised:#f8faff; --surface-raised-2:#ecf1f8; --surface-canvas:#e6edf7; --surface-canvas-2:#f3f6fb; --surface-sunken:#e6ecf5; --surface-overlay:#f5f8fde6; --text-primary:#202b3e; --text-secondary:#58677b; --text-faint:#657388; --text-on-canvas:#20304b; --text-on-canvas-muted:#556b88; --border-subtle:#d9e2ef; --border-strong:#b9c7db; --accent-base:var(--os-accent); --theme-accent:var(--os-accent); --accent-glow:#2979ed25; --font-sans:"Segoe UI Variable","Segoe UI",Arial,"Noto Sans CJK SC",sans-serif; --font-display:var(--font-sans);
  position:absolute; inset:0; overflow:hidden; color:var(--os-ink); font-family:var(--font-sans); font-size:13px; line-height:1.4; -webkit-font-smoothing:antialiased; user-select:none; color-scheme:light;
}
.os-shell *, .os-shell *::before,.os-shell *::after { box-sizing:border-box; }
.os-shell button:not(:where(.package-app-content button)) { appearance:none; border:0; margin:0; padding:0; background:none; color:inherit; font:inherit; text-align:center; cursor:default; outline-offset:3px; -webkit-tap-highlight-color:transparent; }
.os-shell button:focus-visible,.os-shell input:focus-visible { outline:2px solid var(--os-accent); }
.os-shell button:disabled { opacity:.4; }
.os-shell svg { display:block; width:20px; height:20px; flex-shrink:0; }
.os-shell [hidden] { display:none!important; }
.os-shell input { font:inherit; }
.os-shell .wallpaper { position:absolute; inset:0; background-image:asset("wallpaper.svg"); background-size:cover; background-position:center; transition:filter .4s; }
.os-shell .wallpaper-light { position:absolute; inset:-15%; pointer-events:none; opacity:0; background:radial-gradient(ellipse at 25% 20%,#a0ceff44,transparent 48%),radial-gradient(ellipse at 78% 60%,#d0b2ff38,transparent 50%); }
.os-shell.ambient-motion .wallpaper-light { opacity:1; animation:ambient-drift 18s ease-in-out infinite alternate; }
@keyframes ambient-drift { to { transform:translate(8%,5%) rotate(8deg) scale(1.1); opacity:.4; } }
.effect-canvas { position:absolute; inset:0; pointer-events:none; width:100%; height:100%; }
.os-shell.is-dark { --os-ink:#eef3fc; --os-muted:#acb9cd; --os-glass:rgba(27,33,46,.9); --os-panel:#232b3b; --os-line:#ffffff1c; --os-divider:#ffffff12; --os-hover:#ffffff10; --os-shadow:0 22px 65px #0006,0 1px 4px #0004; --surface-raised:#263044; --surface-raised-2:#313b4f; --surface-canvas:#182233; --surface-canvas-2:#212d3e; --surface-sunken:#1c2739; --text-primary:#eaf0f9; --text-secondary:#b1bfd3; --text-faint:#9cacbf; --text-on-canvas:#e4edfa; --text-on-canvas-muted:#b0bed3; --border-subtle:#40516b; color-scheme:dark; }
.os-shell.is-dark .wallpaper { filter:brightness(.65) saturate(.9); }
.os-shell .os-desktop-icons { position:absolute; top:24px; left:18px; bottom:84px; right:18px; display:grid; grid-template-rows:repeat(auto-fill,minmax(104px,104px)); grid-auto-columns:90px; grid-auto-flow:column; align-content:start; justify-content:start; gap:8px 16px; pointer-events:none; }
.os-shell .os-desktop-icon { display:flex; flex-direction:column; align-items:center; justify-content:flex-start; gap:7px; position:relative; width:88px; min-height:94px; padding:9px 4px 6px; border:1px solid transparent; border-radius:5px; color:white; pointer-events:auto; }
.os-shell .os-desktop-icon:hover { background:#ffffff16; border-color:#ffffff20; }
.os-shell .os-desktop-icon.is-selected,.os-shell .os-desktop-icon:focus-visible { background:#d8eaff35; border-color:#ffffff50; }
.os-shell .os-desktop-icon>span:last-of-type { max-width:84px; font-size:12px; line-height:1.45; overflow-wrap:anywhere; text-shadow:0 1px 3px #001246cc,0 0 8px #00124655; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }
.os-shell .app-glyph { position:relative; display:grid; place-items:center; width:var(--os-icon-size); height:var(--os-icon-size); flex-shrink:0; border-radius:10px; color:#fff; background:linear-gradient(145deg,#45b6ff,#2256da); box-shadow:inset 0 1px 1px #ffffff8c,0 2px 5px #12265733; }
.os-shell .app-glyph svg { width:62%; height:62%; stroke-width:1.55; filter:drop-shadow(0 1px 1px #1233); }
.os-shell .app-glyph img { display:block; width:100%; height:100%; object-fit:contain; border-radius:inherit; }
.os-shell .glyph-settings { background:linear-gradient(150deg,#c2c9d4,#6b788e); }.os-shell .glyph-settings svg { width:75%; height:75%; stroke-width:2; }
.os-shell .glyph-start-board { background:linear-gradient(160deg,#ffdf8c,#f2aa30); color:#fff8da; }.os-shell .glyph-start-board svg { width:73%; height:73%; fill:#ffd466; stroke:#b6711880; }
.os-shell .glyph-weather { background:linear-gradient(160deg,#52c9fb,#3b79de); color:#ffe875; }.os-shell .glyph-weather::after{content:"";position:absolute;right:5%;bottom:18%;width:58%;height:24%;border-radius:30px;background:linear-gradient(#fff,#e3edff);box-shadow:0 2px 3px #15396b30}.os-shell .glyph-weather svg{width:62%;height:62%;transform:translate(-15%,-8%);fill:#ffd663;stroke:#ffdb79}
.os-shell .glyph-app-store { background:linear-gradient(155deg,#63c1fd,#2564e9); }.os-shell .glyph-local-apps { background:linear-gradient(145deg,#465770,#142135); color:#a0f1d2; }.os-shell .glyph-browser { background:conic-gradient(from -20deg,#42daca,#3c91ff,#274fc0,#27c8b5,#42daca); }.os-shell .glyph-browser svg { stroke-width:1.25; }
.app-running-dot { position:absolute; top:53px; right:23px; width:7px; height:7px; border-radius:50%; background:#6ee1a3; box-shadow:0 0 0 2px #172c4a; }
.os-shell .menu-bar { display:none; }
.os-shell .taskbar { position:absolute; bottom:0; left:0; right:0; height:54px; background:var(--os-glass); border-top:1px solid var(--os-line); backdrop-filter:blur(42px) saturate(160%); display:flex; align-items:center; justify-content:center; z-index:800; box-shadow:0 -1px 10px #17448708; }
.os-shell .taskbar-center,.os-shell .pinned-apps { display:flex; gap:4px; align-items:center; justify-content:center; height:100%; }
.os-shell .taskbar-center>button,.os-shell .dock-app { width:46px; height:44px; border:1px solid transparent; border-radius:5px; display:grid; place-items:center; position:relative; transition:background 140ms,transform 160ms; }
.os-shell .taskbar-center>button:hover,.os-shell .dock-app:hover { background:var(--os-hover); border-color:var(--os-line); }
.os-shell .taskbar-center>button:active,.os-shell .dock-app:active { transform:scale(.91); }
.os-shell .taskbar .app-glyph { width:var(--dock-icon-size); height:var(--dock-icon-size); border-radius:7px; }
.os-shell .win-mark { display:grid; grid-template-columns:repeat(2,12px); grid-template-rows:repeat(2,12px); gap:2px; transition:transform 160ms; }.win-mark i { background:linear-gradient(135deg,#2584f8,#0861dc); }
.os-shell .search-button svg,.os-shell .view-button svg { width:24px;height:24px; }
.os-shell .dock-label { position:absolute; bottom:calc(100% + 14px); white-space:nowrap; padding:6px 11px; border-radius:6px; color:var(--os-ink); background:var(--os-panel); border:1px solid var(--os-divider); box-shadow:0 5px 15px #0b265925; opacity:0; transform:translateY(5px); pointer-events:none; font-size:12px; transition:opacity 150ms,transform 150ms; }
.os-shell .dock-app:hover .dock-label,.os-shell .dock-app:focus-visible .dock-label { opacity:1; transform:translateY(0); }
.os-shell .running-indicator { position:absolute; width:5px; height:3px; bottom:2px; border-radius:4px; background:var(--os-muted); opacity:0; transition:width 180ms; }
.os-shell .is-running .running-indicator { opacity:1; width:6px; }.os-shell .is-active .running-indicator { width:16px; background:var(--os-accent); }
.os-shell .taskbar-weather { position:absolute; left:17px; display:flex; align-items:center; gap:9px; padding:5px 8px; border-radius:6px; text-align:left; }.taskbar-weather svg { width:28px;height:28px;color:#568acc; }.taskbar-weather span { display:flex; flex-direction:column; }.taskbar-weather strong { font-size:11px;font-weight:550; }.taskbar-weather small { font-size:10px;color:var(--os-muted);margin-top:2px; }
.os-shell .taskbar-tray { position:absolute; right:7px; height:100%; display:flex; gap:3px; align-items:center; }.os-shell .taskbar-tray>button { padding:7px; border-radius:5px; }.os-shell .taskbar-tray>button:hover,.os-shell .taskbar-weather:hover { background:var(--os-hover); }.os-shell .taskbar-tray svg{width:16px;height:16px}.os-shell .tray-clock { display:flex;flex-direction:column;align-items:flex-end;min-width:74px;gap:1px;font-size:11px;line-height:1.45 }.tray-clock small{font-size:10px}.os-shell .taskbar-tray .show-desktop { height:30px;width:5px;padding:0;margin:0 0 0 6px;border-left:1px solid var(--os-divider);border-radius:0; }
.os-shell .dock-separator { width:1px;height:25px;background:var(--os-divider);margin:0 4px;display:none; }
.os-shell .window-layer { position:absolute; inset:0; pointer-events:none; }
.os-shell .shell-window { position:absolute; min-width:0; display:flex; flex-direction:column; pointer-events:auto; background:var(--os-panel); border:1px solid #ffffff7a; border-radius:9px; box-shadow:var(--os-shadow); overflow:hidden; transform-origin:top left; animation:window-appear var(--os-enter) var(--os-ease) both; transition:box-shadow 180ms; }
.os-shell .shell-window:not(.is-active){box-shadow:0 8px 25px #00153e20;border-color:#ffffff30}.os-shell .shell-window.is-active{box-shadow:0 25px 75px #081b4440,0 4px 14px #081b4424;border-color:#ffffffa0}.os-shell .shell-window.is-maximized{border-radius:6px}.os-shell .shell-window.is-dragging{transition:none;opacity:.96}
@keyframes window-appear { from{opacity:0;translate:0 16px;scale:.96}to{opacity:1;translate:0 0;scale:1} }
.os-shell .shell-titlebar { position:relative; display:flex; align-items:center; flex-shrink:0; height:38px; background:var(--os-glass); backdrop-filter:blur(28px); color:var(--os-ink); user-select:none; touch-action:none; border-bottom:1px solid var(--os-divider); }
.os-shell .window-caption { display:flex; align-items:center; gap:9px; min-width:0; padding-left:14px; font-size:12px; flex:1; }.window-caption>span { overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.window-caption svg { width:16px;height:16px;color:var(--os-accent); }
.os-shell .window-controls { order:3; display:flex; flex-direction:row-reverse; height:100%; }.os-shell .window-controls button { width:44px;height:100%;display:grid;place-items:center;transition:background 120ms; }.os-shell .window-controls svg{width:14px;height:14px;stroke-width:1.5}.os-shell .window-controls button:hover { background:var(--os-hover); }.os-shell .window-controls .close-control:hover { background:#df3341;color:white; }.os-shell .window-extras { display:flex;gap:2px; }.os-shell .window-extras button { display:grid;place-items:center;width:30px;height:30px;opacity:.7;border-radius:4px; }.os-shell .window-extras svg { width:14px;height:14px; }.os-shell .window-extras button:hover { background:var(--os-hover);opacity:1; }
.os-shell .shell-window-body { flex:1;min-height:0;position:relative;overflow:hidden;user-select:text; }.os-shell .package-app-content { width:100%;height:100%;overflow:auto;background:var(--os-panel);color:var(--os-ink); }
.os-shell .resize-corner { position:absolute;bottom:0;right:0;width:16px;height:16px;cursor:nwse-resize;background:linear-gradient(135deg,transparent 55%,var(--os-muted) 56%,transparent 61%,transparent 72%,var(--os-muted) 73%,transparent 78%);opacity:.35;touch-action:none;z-index:5; }.os-shell .is-maximized .resize-corner{display:none}
.os-shell .overview-select { display:none; }.os-shell.overview-mode .overview-select{display:block;position:absolute;inset:0;z-index:100}.os-shell.overview-mode .shell-window { outline:1px solid #ffffff70;transition:transform 300ms var(--os-ease),left 300ms var(--os-ease),top 300ms var(--os-ease); }.os-shell.overview-mode .shell-window:hover{outline:5px solid #ffffffc0}.os-shell.overview-mode .wallpaper{filter:blur(12px) brightness(.7);transform:scale(1.04)}.overview-label { position:absolute;left:40px;top:32px;right:40px;z-index:600;color:white;display:flex;align-items:center;gap:16px; }.overview-label strong{font-size:18px}.overview-label span{font-size:12px;opacity:.85}.os-shell .overview-label button{margin-left:auto;padding:8px 20px;background:#fff3;border:1px solid #fff4;border-radius:8px}
.os-shell .snap-preview{position:absolute;z-index:700;top:8px;bottom:60px;left:8px;width:calc(50% - 12px);background:#c6ddff55;border:2px solid #c8e1ffb3;border-radius:12px;backdrop-filter:blur(8px);pointer-events:none;box-shadow:inset 0 0 35px #9ec6ff45;animation:panel-appear 200ms var(--os-ease)}.os-shell .snap-preview[data-side=right]{left:calc(50% + 4px)}.os-shell .snap-preview[data-side=fill]{width:calc(100% - 16px)}
.os-shell .panel-layer { position:absolute;inset:0;pointer-events:none;z-index:900; }.os-shell .shell-panel { pointer-events:auto;position:absolute;border:1px solid var(--os-line);border-radius:10px;background:var(--os-glass);backdrop-filter:blur(45px) saturate(160%);box-shadow:var(--os-shadow);color:var(--os-ink);overflow:hidden;animation:panel-appear var(--os-enter) var(--os-ease) both; }
@keyframes panel-appear { from{opacity:0;translate:0 14px;scale:.985}to{opacity:1;translate:0 0;scale:1} }
.os-shell .panel-launcher,.os-shell .panel-search { width:610px;max-width:calc(100% - 24px);height:auto;max-height:calc(100% - 88px);bottom:66px;left:50%;transform:translateX(-50%);padding:29px 30px 0;overflow:auto; }
.os-shell .launcher-search{display:flex;align-items:center;gap:11px;background:var(--os-panel);border:1px solid var(--os-divider);border-bottom:2px solid var(--os-accent);border-radius:6px;padding:10px 13px;box-shadow:0 1px 3px #28477e08}.launcher-search svg{width:17px;height:17px;color:var(--os-muted)}.os-shell .launcher-search input{width:100%;min-width:0;outline:none;background:none;border:0;color:var(--os-ink);font-size:12px}.launcher-search input::placeholder{color:var(--os-muted)}.launcher-search kbd{white-space:nowrap;font-size:9px;color:var(--os-muted);opacity:.8}
.os-shell .launcher-heading{display:flex;align-items:center;justify-content:space-between;padding:27px 4px 12px;font-size:13px}.os-shell .launcher-heading button{display:flex;align-items:center;gap:4px;font-size:10px;border:1px solid var(--os-divider);padding:4px 9px;border-radius:5px;background:var(--os-hover)}.launcher-heading svg{width:12px;height:12px}
.os-shell .launcher-apps{display:grid;grid-template-columns:repeat(6,1fr);gap:4px;min-height:172px;align-content:start;padding-bottom:10px;max-height:265px;overflow:auto}.os-shell .launcher-apps button{display:flex;flex-direction:column;gap:9px;align-items:center;padding:12px 4px 9px;border-radius:6px}.os-shell .launcher-apps button:hover{background:var(--os-hover)}.os-shell .launcher-apps .app-glyph{width:34px;height:34px;border-radius:8px}.launcher-apps button>span:last-child{font-size:11px;line-height:1.4;max-width:80px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.os-shell .launcher-apps.list-view{grid-template-columns:1fr 1fr}.os-shell .launcher-apps.list-view button{flex-direction:row;text-align:left;gap:14px;padding-left:12px}.os-shell .launcher-apps.list-view button>span:last-child{max-width:none}.no-results{grid-column:1/-1;font-size:12px;text-align:center;color:var(--os-muted);padding:35px 0}
.os-shell .recent-heading{display:flex;justify-content:space-between;font-size:13px;padding:10px 4px 14px}.recent-heading>span{font-size:10px;color:var(--os-muted)}.os-shell .recent-apps{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding:0 0 22px;min-height:100px}.os-shell .recent-apps button{display:flex;text-align:left;align-items:center;gap:11px;padding:10px;border-radius:7px}.os-shell .recent-apps button:hover{background:var(--os-hover)}.os-shell .recent-apps .app-glyph{width:30px;height:30px;border-radius:7px}.recent-apps button>span:last-child{display:flex;flex-direction:column;gap:3px}.recent-apps strong{font-size:11px;font-weight:500}.recent-apps small{font-size:10px;color:var(--os-muted)}.empty-recents{display:flex;align-items:center;gap:14px;grid-column:1/-1;padding:12px 16px;color:var(--os-muted);font-size:12px}.empty-recents svg{width:33px;height:33px;opacity:.65}
.os-shell .launcher-footer{display:flex;align-items:center;gap:10px;padding:16px 28px;margin:0 -30px;background:var(--os-hover);border-top:1px solid var(--os-divider);font-size:11px}.user-avatar{width:29px;height:29px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,#548aca,#879fd5);color:white;font-size:13px}.launcher-footer strong{font-weight:500}.os-shell .launcher-footer button{display:flex;align-items:center;gap:7px;padding:6px 8px;border-radius:6px;font-size:11px}.os-shell .launcher-footer button:first-of-type{margin-left:auto}.launcher-footer svg{width:16px;height:16px}.os-shell .launcher-footer button:hover{background:var(--os-hover)}
.os-shell .panel-controls,.os-shell .panel-calendar,.os-shell .panel-widgets,.os-shell .panel-connection{right:12px;bottom:66px;width:360px;max-width:calc(100% - 24px);padding:20px;max-height:calc(100% - 90px);overflow:auto}.os-shell .shell-panel>header{display:flex;align-items:center;justify-content:space-between;font-size:13px;font-weight:600;margin-bottom:16px}.os-shell .shell-panel>header button{display:grid;place-items:center;padding:3px;border-radius:5px;color:var(--os-muted)}.shell-panel>header svg{width:15px;height:15px}.os-shell .control-tiles{display:grid;grid-template-columns:1fr 1fr;gap:9px}.os-shell .control-tiles button{display:flex;flex-direction:column;align-items:flex-start;padding:13px 14px;gap:6px;border-radius:9px;border:1px solid var(--os-divider);background:var(--os-hover);text-align:left}.os-shell .control-tiles button[aria-pressed=true]{background:var(--os-accent);color:white;border-color:transparent}.control-tiles svg{width:21px;height:21px;margin-bottom:5px}.control-tiles strong{font-size:12px;font-weight:550}.control-tiles small{font-size:10px;opacity:.85}.os-shell .effect-range{display:flex;align-items:center;justify-content:space-between;gap:22px;font-size:12px;margin:22px 0}.effect-range span{white-space:nowrap}.os-shell input[type=range]{accent-color:var(--os-accent);width:185px;max-width:65%;height:16px;cursor:pointer}.accent-options{display:flex;align-items:center;gap:9px;margin:22px 0;font-size:12px}.accent-options>span{margin-right:auto}.os-shell .accent-options button{background:var(--swatch);width:22px;height:22px;border-radius:50%;border:2px solid var(--os-panel);box-shadow:0 0 0 1px var(--os-divider)}.os-shell .accent-options button[aria-pressed=true]{box-shadow:0 0 0 2px var(--os-ink)}.os-shell .ambient-option{display:flex;align-items:center;gap:9px;width:100%;font-size:12px;padding:12px 0;border-top:1px solid var(--os-divider)}.ambient-option svg{width:17px;height:17px}.ambient-option span{margin-left:auto;font-size:10px;color:var(--os-accent)}.os-shell .panel-controls>footer{margin:12px -20px -20px;padding:13px 16px;background:var(--os-hover);border-top:1px solid var(--os-divider)}.os-shell .panel-controls>footer button{display:flex;align-items:center;gap:8px;width:100%;font-size:11px}.panel-controls>footer svg{width:16px;height:16px}.panel-controls>footer svg:last-child{margin-left:auto}
.calendar-date{display:flex;align-items:center;gap:18px;margin:12px 0 26px}.calendar-date>strong{font-size:56px;line-height:1;font-weight:350;letter-spacing:-3px}.calendar-date>span{max-width:150px;color:var(--os-muted);font-size:12px;line-height:1.6}.calendar-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;font-size:12px;text-align:center}.calendar-grid>span{height:35px;display:grid;place-items:center;border-radius:50%}.calendar-grid .weekday{color:var(--os-muted);font-size:10px}.calendar-grid .today{background:var(--os-accent);color:white}.calendar-summary{display:flex;align-items:center;gap:10px;font-size:11px;margin:20px 0 2px;padding-top:16px;border-top:1px solid var(--os-divider);color:var(--os-muted)}.calendar-summary svg{width:17px;height:17px}.connection-info{display:flex;flex-direction:column;align-items:center;text-align:center;gap:13px;padding:18px 0}.connection-info>svg{width:40px;height:40px;color:var(--os-accent)}.connection-info strong{font-size:14px}.connection-info p{font-size:11px;color:var(--os-muted)}
.os-shell .menu-popover,.os-shell .context-popover { width:240px;padding:6px;left:10px;top:38px;border-radius:9px; }.os-shell .menu-popover button,.os-shell .context-popover button{display:flex;align-items:center;gap:10px;width:100%;padding:9px 10px;border-radius:5px;text-align:left;font-size:12px}.os-shell .menu-popover button:hover,.os-shell .context-popover button:hover{background:var(--os-accent);color:white}.menu-popover svg,.context-popover svg{width:16px;height:16px}.menu-popover svg:last-child{margin-left:auto;width:12px;height:12px}.os-shell.windows .menu-popover{top:auto;bottom:64px;left:50%;transform:translateX(-50%)}.os-shell .snap-menu{width:218px;padding:14px}.snap-menu strong{font-size:11px;font-weight:500}.snap-menu>div{display:flex;gap:12px;margin-top:13px}.os-shell .snap-menu button{padding:7px;border-radius:6px;color:var(--os-muted)}.os-shell .snap-menu button:hover{background:var(--os-accent);color:white}.snap-menu svg{width:36px;height:36px}
