.os-shell .os-desktop-icon>.app-glyph { max-height:none; max-width:none; padding:0; backdrop-filter:none; -webkit-line-clamp:unset; overflow:visible; }
.os-shell .os-desktop-icon>span:last-of-type { background:none; backdrop-filter:none; padding:1px 2px; width:auto; max-height:none; border-radius:3px; }
.os-shell .os-desktop-icon>.app-glyph { box-shadow:inset 0 1px 1px #ffffff8c,0 2px 5px #12265733; }

.os-shell button[data-action=connection]{position:relative}.os-shell .service-unavailable::after{content:"";position:absolute;right:5px;top:3px;width:5px;height:5px;border-radius:50%;background:#d68a24;box-shadow:0 0 0 1px var(--os-glass)}

