/* System tools are part of the package, including their layout and native controls. */
:host,:desktop{--sys-font:"Segoe UI Variable","Segoe UI",Arial,"Noto Sans CJK SC",sans-serif;--sys-bg:#f3f3f3;--sys-content:#f8f8f8;--sys-sidebar:#f0f0f0;--sys-row:#fff;--sys-hover:#00000005;--sys-selected:#0000000b;--sys-line:#0000000f;--sys-ink:#1c1c1c;--sys-muted:#626262;--sys-control:#fff;--sys-control-line:#00000029;--sys-shadow:0 1px 2px #0000000d;--sys-radius:7px;--sys-accent:var(--system-accent,#2979ed);--font-sans:var(--sys-font);--font-display:var(--sys-font);--text-primary:var(--sys-ink);--text-secondary:var(--sys-muted);--text-faint:var(--sys-muted);--surface-raised:var(--sys-row);--surface-raised-2:var(--sys-content);--surface-canvas:var(--sys-bg);--surface-sunken:var(--sys-sidebar);--border-hairline-ink:var(--sys-line);--border-subtle:var(--sys-line);--accent-base:var(--sys-accent);--theme-accent:var(--sys-accent);--text-on-accent:#fff;--focus-ring:var(--sys-accent)}
:host[data-system-appearance=macos],:desktop[data-system-appearance=macos]{--sys-font:-apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,"Noto Sans CJK SC",sans-serif;--sys-bg:#f3f3f3;--sys-content:#f4f4f4;--sys-sidebar:#e9e9ebd9;--sys-row:#fff;--sys-hover:#00000006;--sys-selected:#0000000c;--sys-line:#00000015;--sys-control-line:#00000026;--sys-radius:10px}
:host[data-system-color-scheme=dark],:desktop[data-system-color-scheme=dark]{--sys-bg:#202020;--sys-content:#252525;--sys-sidebar:#202020e0;--sys-row:#2d2d2d;--sys-hover:#ffffff09;--sys-selected:#ffffff12;--sys-line:#ffffff0e;--sys-ink:#f4f4f4;--sys-muted:#b9b9b9;--sys-control:#383838;--sys-control-line:#ffffff22;--sys-shadow:0 1px 2px #0003;color-scheme:dark}
